using System;
using System.Collections.Generic;

public class UserSession
{
    public string UserId { get; set; } = "user_42";
    public string? CurrentActiveToken { get; set; } = "token_v1";
    public HashSet<string> RevokedTokens { get; } = new();
}

public class AuthService
{
    private readonly UserSession _session = new();

    public (bool success, string? newToken, string message) RotateRefreshToken(string incomingToken)
    {
        if (_session.RevokedTokens.Contains(incomingToken))
        {
            _session.CurrentActiveToken = null; // Hanguskan seluruh sesi aktif!
            return (false, null, "SECURITY ALERT: Token reuse detected! All sessions terminated.");
        }

        if (incomingToken != _session.CurrentActiveToken)
        {
            return (false, null, "Invalid token.");
        }

        _session.RevokedTokens.Add(incomingToken);
        var newToken = "token_v" + Guid.NewGuid().ToString("N")[..6];
        _session.CurrentActiveToken = newToken;

        return (true, newToken, "Token rotated successfully.");
    }
}

public class Program
{
    public static void Main()
    {
        var auth = new AuthService();

        Console.WriteLine("--- Pertukaran Sesi 1 (User Sah) ---");
        var res1 = auth.RotateRefreshToken("token_v1");
        Console.WriteLine($"Sukses: {res1.success} | Token Baru: {res1.newToken} | Pesan: {res1.message}");

        Console.WriteLine("\n--- Hacker Mencoba Memakai Ulang token_v1 ---");
        var resHack = auth.RotateRefreshToken("token_v1");
        Console.WriteLine($"Sukses: {resHack.success} | Pesan: {resHack.message}");
    }
}
